def _cards(state):
    """Index physical openers, preserving ambiguity when labels are duplicated."""
    labeled = {e['id']: name for name, e in visible_products(state).items()}
    result = {}
    for e in state.get('elements', ()):
        if (e.get('role') not in ('Button','ListItem','Hyperlink') or e.get('kind') != 'click'
                or not e.get('enabled') or e.get('clipped') or e.get('menu_category') or needs_confirmation(e)):
            continue
        name = e.get('menu_product') or _product_name(e['role'], e['name']) or labeled.get(e['id'])
        if name:
            result.setdefault(name, []).append(e)
    return result


def _hidden(state):
    for hint in state.get('scroll_candidates', ()):
        if hint.get('kind') == 'product':
            yield hint['item'], hint
        elif hint.get('kind') == 'named' and (match := menu_price_label(hint['name'])):
            yield match[1], hint


def opening_expectation(state, goal, plan, target):
    if state.get('draft_item') or state.get('order_detail') or state.get('order_dialog'):
        return None
    opener = plan.get('screen_opener') or {}
    route = plan.get('category_route') or {}
    item = opener.get('item') or (route.get('item') if route.get('kind') == 'product' else None)
    if not item:
        if plan.get('workflow_role') or plan.get('checkout_route') or route:
            return None
        cards = _cards(state)
        names = set(cards) | {name for name, _ in _hidden(state)} | set(state.get('published_menu', {}))
        message = plan['decision'].get('message', '')
        named = [n for n in names if _plain(n) in _plain(goal) and re.search(
            re.escape(_plain(n)) + r'(?:을|를|의)?(?:상품을?|메뉴를?)?(?:옵션을?열|추가|담|선택)', _plain(message))]
        if len(named) == 1:
            item = named[0]
        else:
            matched = [n for n, controls in cards.items() if _plain(n) in _plain(goal)
                       and any(e['id'] == target['id'] for e in controls)]
            if len(matched) == 1:
                item = matched[0]
    if item:
        return dict(item=item, binding=_binding(state), cart=_summary(state), clicked=target['name'],
                    was_category=bool(target.get('menu_category')), attempts=1, dismissed=False)


def _action(role, action, message, target=''):
    return dict(schema_valid=True, workflow_role=role,
                decision=dict(action=action, target_id=target, text='', evidence='', message=message))


def verify_opener(state, pending, history):
    """None means that this observation positively identified the intended editor."""
    item = pending['item']
    def stop(message):
        return _action('product_open_unverified', 'wait_user', message)

    if _binding(state) != pending['binding']:
        return stop('상품을 연 뒤 키오스크 창이나 페이지가 바뀌었습니다. 주문표를 확인해 주세요.')
    draft = state.get('draft_item') or dialog_item(state) or (state.get('order_dialog') or {}).get('item')
    if draft and _plain(draft) == _plain(item):
        return None
    if draft:
        close = state.get('draft_dismiss_id')
        if not close or pending['dismissed']:
            return stop(f'요청한 {item} 대신 {draft} 옵션 창이 열려 있습니다. 창을 닫으면 다시 찾겠습니다.')
        return _action('wrong_product_dismiss', 'click',
                       f'{item} 대신 {draft} 옵션 창이 열려 닫고 요청한 상품을 다시 찾습니다.', close)
    if state.get('draft_quantity_ids') or state.get('order_detail') or state.get('order_dialog'):
        return stop('열린 옵션 창의 상품명을 읽지 못했습니다. 주문표에 담기 전에 현재 상품을 확인해 주세요.')
    cart = _summary(state)
    if (pending['cart'] != cart or (cart is None and not pending['was_category'])
            or state.get('checkout_sheet') or state.get('order_sheet')):
        return stop('상품을 연 뒤 장바구니가 그대로인지 확인할 수 없습니다. 중복으로 담지 않도록 주문표를 확인해 주세요.')
    if pending['attempts'] >= 3:
        return stop(f'{item} 옵션 창이 열렸는지 확인하지 못했습니다. 현재 상품을 확인해 주세요.')
    controls = [e for name, entries in _cards(state).items() if _plain(name) == _plain(item) for e in entries]
    if len(controls) == 1:
        return _action('product_open_retry', 'click',
                       f'{item} 옵션 창이 열리지 않아 현재 화면에서 찾은 상품 버튼을 다시 누릅니다.', controls[0]['id'])
    hints = [h for name, h in _hidden(state) if _plain(name) == _plain(item)]
    if not controls and len(hints) == 1:
        plan = reveal_scroll_target(state, history, hints[0])
        if plan:
            plan['workflow_role'] = 'product_open_reveal'
            return plan
    return stop(f'{item} 옵션 창이 열리지 않았고, 현재 화면에서 해당 상품을 하나로 구분할 수 없습니다.')

def has_order_products(state):
    """A clipped product can establish a menu and guide a scroll, never a click."""
    return bool(visible_products(state) or any(
        hint.get('kind') == 'product' and is_catalog_label(hint.get('item'))
        for hint in state.get('scroll_candidates', ())))

